function Editor({ project, draft, drafts }: { project: ProjectRecord; draft: DraftRecord | null; drafts: DraftSummary[] }) {
  const { tab, mode } = Route.useSearch()
  const navigate = Route.useNavigate()
  const toast = useToast()
  const confirm = useConfirm()
  const renameFn = useServerFn(renameProjectFn)

  const [name, setName] = useState(project.name)
  const savedName = useRef(project.name)
  // The committed name drives the page title (the route's loader data keeps the name from load time).
  const [titleName, setTitleName] = useState(project.name)
  useEffect(() => {
    document.title = pageTitle(tab, titleName, draft?.label)
  }, [tab, titleName, draft?.label])
  // AI generated by: Claude Code / claude-opus-5-5
  // Prompt: "ok its looks good i agree with the findings, now i want you to dig into the problem and implement the changes"
  // Changes: Document, autosave, conflicts and view state live in the project session.
  const session = useProjectSession(draft ? { project, draft } : project)
  const { data, conflict, edit: update, readOnly } = session

  // AI generated by: Claude Code / claude-opus-5-5
  // Prompt: "ok its looks good i agree with the findings, now i want you to dig into the problem and implement the changes"
  // Changes: One analysed grammar G = (N, T, P, S) from the grammar module; rules and definition are deferred
  //          together so every tab sees the same snapshot.
  // AI generated by: Claude Code / claude-opus-5-5
  // Prompt: "Parts and content analysis (prefactor)"
  // Changes: The grammar texts come from the analysis entry point's grammarSource (the same source the server uses).
  // grammarSource reads only the grammar rules and the definition.
  // eslint-disable-next-line react-hooks/exhaustive-deps
  const source = useDeferredValue(useMemo(() => grammarSource(data), [data.ll.grammar, data.def]))
  const grammar = useMemo(() => analyzeGrammar(source), [source])

  const commitName = async () => {
    const next = name.trim()
    if (!next) return setName(savedName.current)
    if (next === savedName.current) return
    try {
      await renameFn({ data: { id: project.id, name: next } })
      savedName.current = next
      setTitleName(next)
    } catch (err) {
      setName(savedName.current)
      toast({ title: 'Premenovanie zlyhalo', description: err instanceof Error ? err.message : String(err), tone: 'bad' })
    }
  }

  // AI generated by: Claude Code / claude-opus-5-5
  // Prompt: "ok its looks good i agree with the findings, now i want you to dig into the problem and implement the changes"
  // Changes: The session saves local edits first and refuses (throws a Slovak message) if it cannot.
  const importData = async (imported: ProjectData, fileName: string) => {
    await session.importData(imported, `Pred importom ${fileName}`)
    toast({ title: 'Projekt importovaný', description: fileName, tone: 'ok' })
  }

  const status = readOnly ? READ_ONLY_STATUS : STATUS[session.status]
  const statusText = session.status === 'failed' && session.error ? `${status.text}: ${session.error}` : status.text
  const resolveTheirs = async () => {
    const ok = await confirm({
      title: 'Načítať verziu zo servera?',
      body: session.conflictParts.length
        ? `Tvoje neuložené zmeny v časti ${partList(session.conflictParts)} sa zahodia. Ostatné tvoje zmeny sa uložia.`
        : 'Tvoje neuložené zmeny sa zahodia.',
      confirmLabel: 'Zahodiť a načítať',
      tone: 'danger',
    })
    if (ok) void session.resolveConflict('theirs')
  }

  return (
    // AI generated by: Claude Code / claude-opus-5-5
    // Prompt: "make the right pane scrollable insted it being rendered whole, the page should stay constant"
    // Changes: Definícia tab on wide screens – small bottom padding so the page itself fits the viewport (columns scroll inside).
    // AI generated by: Claude Code / claude-opus-5-5
    // Prompt: "make sure the layout stays fixed verticaly, make the left and right pane scrollable instead"
    // Changes: The LL tab also fits the viewport (its columns scroll inside).
    <div className={cx('mx-auto max-w-[1440px] px-4 pb-16 sm:px-6', (tab === 'def' || tab === 'll') && 'lg:pb-3')}>
      <header className="sticky top-0 z-20 -mx-4 mb-5 border-b border-white/5 bg-canvas/85 px-4 py-3 backdrop-blur-xl sm:-mx-6 sm:px-6">
        <div className="flex flex-wrap items-center gap-x-4 gap-y-3">
          <Link to="/" className="rounded text-sm text-zinc-400 hover:text-zinc-100">
            ← Projekty
          </Link>
          <input
            value={name}
            onChange={(e) => setName(e.target.value)}
            onBlur={() => void commitName()}
            onKeyDown={(e) => {
              if (e.key !== 'Enter') return
              e.preventDefault()
              // IME-safe: the Enter that confirms a composition must not commit the name.
              if (isCommitEnter(e.nativeEvent)) e.currentTarget.blur()
            }}
            maxLength={PROJECT_NAME_MAX}
            readOnly={readOnly}
            enterKeyHint="done"
            aria-label="Názov projektu"
            className="min-w-0 flex-1 basis-48 rounded-lg border border-transparent bg-transparent px-2 py-1 text-lg font-semibold text-zinc-100 hover:border-white/10 focus:border-indigo-400/50 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-indigo-400"
          />
          {/* AI generated by: Claude Code / claude-opus-5-5
              Prompt: "ok its looks good i agree with the findings, now i want you to dig into the problem and implement the changes"
              Changes: The visible status is not a live region (no announcement per edit); only problems are announced. */}
          <div className="flex items-center gap-2 text-xs text-zinc-400" title={session.error ?? undefined}>
            <span aria-hidden="true" className={cx('h-2 w-2 shrink-0 rounded-full', status.dot)} />
            {statusText}
            {session.status === 'saved' && !readOnly && <span className="text-zinc-400">{new Date(session.savedAt).toLocaleTimeString('sk-SK')}</span>}
          </div>
          <span className="sr-only" role="status">
            {status.alert && session.status !== 'conflict' ? statusText : ''}
          </span>
          {/* Sections are real links (the section lives in ?tab=); the current one is aria-current="page" and is
              marked by background + underline bar (styles.css .section-link), not by colour alone.
              Switching sections keeps the chosen LL mode. */}
          <DraftSwitcher drafts={drafts} current={draft?.id ?? null} />
          <nav aria-label="Sekcie projektu" className="w-full lg:w-auto">
            <ul className="flex flex-wrap justify-center gap-1">
              {TABS.map((t) => (
                <li key={t.id}>
                  <Link
                    from={Route.fullPath}
                    to="."
                    search={(prev) => ({ ...prev, tab: t.id })}
                    replace
                    aria-current={t.id === tab ? 'page' : undefined}
                    className="section-link block rounded-full px-3 py-1.5 text-sm transition-colors max-sm:px-2 max-sm:text-xs"
                  >
                    {t.label}
                  </Link>
                </li>
              ))}
            </ul>
          </nav>
        </div>
      </header>

      <main>
        <h1 className="sr-only">
          {tabLabel(tab)} – {draft ? `Návrh „${draft.label}“ – ` : ''}
          {titleName}
        </h1>
        {session.draft && <DraftBanner draft={session.draft} readOnly={readOnly} />}
        {/* AI generated by: Claude Code / claude-opus-5-5
            Prompt: "ok its looks good i agree with the findings, now i want you to dig into the problem and implement the changes"
            Changes: Announced as an alert; discarding local edits asks first; both choices go through the session. */}
        {conflict && (
          <div role="alert" className="mb-5 flex flex-wrap items-center gap-3 rounded-2xl border border-rose-400/30 bg-rose-500/10 px-4 py-3 text-sm text-rose-100">
            <div className="min-w-0 flex-1">
              {/* AI generated by: Claude Code / claude-opus-5-5
                  Prompt: "Human edits drafts"
                  Changes: In a draft the prompt names the part both sides changed. */}
              {session.conflictParts.length ? (
                <>
                  Návrh medzitým zmenil niekto iný ({new Date(conflict.updatedAt).toLocaleTimeString('sk-SK')}) v tej istej časti, ktorú upravuješ:{' '}
                  <strong>{partList(session.conflictParts)}</strong>. Tvoje zmeny v nej zatiaľ neboli uložené.
                </>
              ) : (
                <>
                  Projekt medzitým zmenil niekto iný (iná karta alebo kolega, {new Date(conflict.updatedAt).toLocaleTimeString('sk-SK')}). Tvoje zmeny
                  zatiaľ neboli uložené.
                </>
              )}
            </div>
            <Button onClick={() => void resolveTheirs()}>
              Načítať verziu zo servera
            </Button>
            <PrimaryButton onClick={() => void session.resolveConflict('mine')}>
              Prepísať mojou verziou
            </PrimaryButton>
          </div>
        )}

        {/* AI generated by: Claude Code / claude-opus-5-5
            Prompt: "could you add a tab where i will be able to define properties"
            Changes: Render the Definition tab. */}
        <ReadOnlyProvider value={readOnly}>
        <InDraftProvider value={session.draft !== null}>
        {tab === 'def' && <DefinitionTab data={data} update={update} grammar={grammar} />}
        {/* AI generated by: Claude Code / claude-opus-5-5
            Prompt: "i changed my mind move the previous pane and this one into separate \"overview\" tab"
            Changes: Overview tab. */}
        {tab === 'overview' && <OverviewTab grammar={grammar} />}
        {/* AI generated by: Claude Code / claude-opus-5-5
            Prompt: "Now i want this change. the LL tab should be split into two, rather it should have 2 modes:\n- simulation\n- viewer"
            Changes: LL tab gets its mode from the URL. */}
        {tab === 'll' && (
          <LLTab
            data={data}
            update={update}
            grammar={grammar}
            // AI generated by: Claude Code / claude-opus-5-5
            // Prompt: "ok its looks good i agree with the findings, now i want you to dig into the problem and implement the changes"
            // Changes: Simulation step/speed is per-project view state owned by the session (outside the document).
            sim={session.view.llSim}
            onSim={(fn) => session.updateView((v) => ({ ...v, llSim: fn(v.llSim) }))}
            mode={mode ?? 'sim'}
            onMode={(m) => void navigate({ search: (prev) => ({ ...prev, mode: m }), replace: true })}
          />
        )}
        {tab === 'prec' && <PrecTab data={data} update={update} />}
        {tab === 'export' && <ExportTab name={name} data={data} update={update} grammar={grammar} onImport={importData} />}
        {/* AI generated by: Claude Code / claude-opus-5-5
            Prompt: "ok its looks good i agree with the findings, now i want you to dig into the problem and implement the changes"
            Changes: History operations go through the session (save first, refuse loudly). */}
        {/* AI generated by: Claude Code / claude-opus-5-5
            Prompt: "Human edits drafts"
            Changes: A draft's history stays read-only here until draft history operations exist. */}
        {tab === 'history' && (
          <ReadOnlyProvider value={readOnly || draft !== null}>
            <HistoryTab projectId={project.id} draftId={draft?.id} onSaveVersion={session.saveNamedVersion} onRestore={session.restoreVersion} />
          </ReadOnlyProvider>
        )}
        </InDraftProvider>
        </ReadOnlyProvider>
      </main>
    </div>
  )
}
